          opacity: openModal ? "1" : "0",
        },
        { at: 0.2 * numbColumns },
      ],
    ] as AnimationSequence;
    animate(sequence);
  }, [openModal, animate]);
  const [state, formAction] = useFormState<FormState, FormData>(
    contactFormAction,
    initialState
  );
