              className="dark:invert-[.6]"
              style={{ objectFit: "cover", animation: "fadeIn 5s" }}
            />
          </button>
          <form
            action={formAction}
            id="contact_form__c"
            className="absolute top-28 w-screen p-10 md:p-14 flex justify-center flex-col items-center"
          >
            <input
              type="text"
