'use client'

import { useState } from 'react'
import { useMotionValueEvent, useScroll } from 'framer-motion'

export const useHasScrolled = (): { hasScrolled: boolean } => {
  const [hasScrolled, setHasScrolled] = useState(false)
  const { scrollYProgress } = useScroll()
  useMotionValueEvent(scrollYProgress, 'change', (latest) => {
    if (latest > 0) {
      setHasScrolled(true)
    } else {
      setHasScrolled(false)
    }
  })
  return { hasScrolled }
}

"use client";

import { useEffect, useState } from "react";
import { useCookies } from "next-client-cookies";

export const useIsDM = () => {
  const cookies = useCookies();
  let dmCookie = cookies.get("x-theme");
  if (!dmCookie) dmCookie = "dark";
  const [isDM, setIsDM] = useState(dmCookie === "dark");
  useEffect(() => {
    setIsDM(dmCookie === "dark");
  }, [dmCookie]);

  return isDM;
};

"use client";

import { createContext, useContext, useEffect, useState } from "react";
import MobileDetect from "mobile-detect";
import { useWindowWidth } from "@react-hook/window-size";

interface ContextValue {
  me?: any;
  userAgent: string;
}

export const SSRDataContext = createContext<ContextValue>({} as ContextValue);

export function useSSRDataContext() {
  return useContext(SSRDataContext);
}
export const useIsMobile = () => {
  const [isMobile, setIsMobile] = useState(false);
  const { userAgent } = useSSRDataContext();
  const mobileDetect = new MobileDetect(userAgent);
  const userAgentIsDesktop = !mobileDetect.mobile() && !mobileDetect.tablet();
  const isSSR = typeof window === "undefined";
  const windowWidth = useWindowWidth();

  useEffect(() => {
    if (isSSR) {
      setIsMobile(!userAgentIsDesktop);
    }

    setIsMobile(windowWidth <= 768);
  }, [userAgentIsDesktop, windowWidth, isSSR]);

  return isMobile;
};

